Certainly! Below is a complete implementation of a singly linked list in C. This implementation includes functions to create a new node, insert nodes at the beginning and end, delete nodes, search for a node, and print the list.

```c
#include <stdio.h>
#include <stdlib.h>

// Define the structure for a node in the linked list
struct Node {
    int data;
    struct Node* next;
};

// Function to create a new node
struct Node* createNode(int data) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    if (newNode == NULL) {
        printf("Memory allocation failed!\n");
        exit(1);
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Function to insert a node at the beginning of the list
void insertAtBeginning(struct Node** head, int data) {
    struct Node* newNode = createNode(data);
    newNode->next = *head;
    *head = newNode;
}

// Function to insert a node at the end of the list
void insertAtEnd(struct Node** head, int data) {
    struct Node* newNode = createNode(data);
    if (*head == NULL) {
        *head = newNode;
        return;
    }
    struct Node* temp = *head;
    while (temp->next != NULL) {
        temp = temp->next;
    }
    temp->next = newNode;
}

// Function to delete a node with a specific data value
void deleteNode(struct Node** head, int data) {
    struct Node* temp = *head;
    struct Node* prev = NULL;

    // If the node to be deleted is the head node
    if (temp != NULL && temp->data == data) {
        *head = temp->next;
        free(temp);
        return;
    }

    // Search for the node to be deleted
    while (temp != NULL && temp->data != data) {
        prev = temp;
        temp = temp->next;
    }

    // If the node was not found
    if (temp == NULL) {
        printf("Node with data %d not found!\n", data);
        return;
    }

    // Unlink the node from the list
    prev->next = temp->next;
    free(temp);
}

// Function to search for a node with a specific data value
struct Node* searchNode(struct Node* head, int data) {
    struct Node* temp = head;
    while (temp != NULL) {
        if (temp->data == data) {
            return temp;
        }
        temp = temp->next;
    }
    return NULL;
}

// Function to print the linked list
void printList(struct Node* head) {
    struct Node* temp = head;
    while (temp != NULL) {
        printf("%d -> ", temp->data);
        temp = temp->next;
    }
    printf("NULL\n");
}

// Function to free the entire linked list
void freeList(struct Node** head) {
    struct Node* temp;
    while (*head != NULL) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

int main() {
    struct Node* head = NULL;

    // Insert nodes at the beginning and end
    insertAtBeginning(&head, 10);
    insertAtEnd(&head, 20);
    insertAtEnd(&head, 30);
    insertAtBeginning(&head, 5);

    // Print the list
    printf("Linked List: ");
    printList(head);

    // Search for a node
    int searchData = 20;
    struct Node* foundNode = searchNode(head, searchData);
    if (foundNode != NULL) {
        printf("Node with data %d found!\n", searchData);
    } else {
        printf("Node with data %d not found!\n", searchData);
    }

    // Delete a node
    int deleteData = 20;
    deleteNode(&head, deleteData);
    printf("Linked List after deleting %d: ", deleteData);
    printList(head);

    // Free the list
    freeList(&head);

    return 0;
}
```

### Explanation:
1. **Node Structure**: The `Node` structure contains an integer `data` and a pointer `next` to the next node in the list.
2. **createNode**: Allocates memory for a new node and initializes it with the given data.
3. **insertAtBeginning**: Inserts a new node at the beginning of the list.
4. **insertAtEnd**: Inserts a new node at the end of the list.
5. **deleteNode**: Deletes a node with a specific data value from the list.
6. **searchNode**: Searches for a node with a specific data value and returns it if found.
7. **printList**: Prints the entire linked list.
8. **freeList**: Frees the memory allocated for the entire linked list.

### Usage:
- The `main` function demonstrates how to use these functions to create, manipulate, and free a linked list.

This implementation is a basic example and can be extended to include more features such as inserting at a specific position, reversing the list, or implementing a doubly linked list.

